import{_ as o,r as s,o as l,c as p,e,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Color Picker Field - October CMS - 3.x","titleTemplate":false,"description":"Form Widget","frontmatter":{"subtitle":"Form Widget","shortname":"Color Picker"},"headers":[{"level":2,"title":"Dynamic Available Colors","slug":"dynamic-available-colors","link":"#dynamic-available-colors","children":[]}],"relativePath":"3.x/element/form/widget-colorpicker.md","filePath":"3.x/element/form/widget-colorpicker.md"}'),i={name:"3.x/element/form/widget-colorpicker.md"};function d(u,a,k,m,h,g){const n=s("pre-heading"),t=s("post-heading");return l(),p("div",null,[e(n),a[0]||(a[0]=c("h1",null,"Color Picker Field",-1)),e(t),a[1]||(a[1]=r(`<p><code>colorpicker</code> - renders controls to select a hexadecimal color value.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">color</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Background
    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
</code></pre></div><p>The following <a href="./../form-fields.html">field properties</a> are supported and commonly used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>default</strong></td><td>specifies a default string value, optional.</td></tr><tr><td><strong>comment</strong></td><td>places a descriptive comment below the field.</td></tr><tr><td><strong>availableColors</strong></td><td>list of available colors as an array.</td></tr><tr><td><strong>allowEmpty</strong></td><td>allows empty input value. Default: <code>false</code></td></tr><tr><td><strong>allowCustom</strong></td><td>allows selection of a custom color. Default: <code>true</code></td></tr><tr><td><strong>showAlpha</strong></td><td>displays an opacity slider and sets an 8-digit hex code. Default: <code>false</code></td></tr><tr><td><strong>showInput</strong></td><td>displays a text input next to the color picker and disables available colors. Default: <code>false</code></td></tr></tbody></table></div><p>You may define preset colors by setting the <code>availableColors</code> property to an array value of hex colors. The <code>allowCustom</code> property can be used to disable the selection of a custom color, and this is optional.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">color</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Background
    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
    <span class="token key atrule">availableColors</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&#39;#000000&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;#111111&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;#222222&#39;</span><span class="token punctuation">]</span>
    <span class="token key atrule">allowCustom</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><div class="custom-block tip"><p>If the <code>availableColors</code> field in not defined in the YAML file, the colorpicker uses a set of 20 default colors.</p></div><p>Use the <code>showAlpha</code> property to include opacity in the color selection and this produces an 8-digit hex value.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">color</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Background
    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
    <span class="token key atrule">showAlpha</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>Use the <code>showInput</code> property to display a text input next to the color. This mode will disable the available colors and make choosing and entering a custom hex color the primary focus.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">color</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Primary Color
    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
    <span class="token key atrule">showInput</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><h2 id="dynamic-available-colors"><a href="#dynamic-available-colors" class="header-anchor">#</a> Dynamic Available Colors</h2><p>The available colors can be sourced from the model class by setting <code>availableColors</code> as a method name declared in the model class. This method should return an array of hex colors in the same format as in the example above. The first argument of this method is the field name, the second is the currect value of the field, and the third is the current data object for the entire form.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">color</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Background
    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
    <span class="token key atrule">availableColors</span><span class="token punctuation">:</span> myColorList
</code></pre></div><p>Supplying the available colors in the model class:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">myColorList</span><span class="token punctuation">(</span><span class="token variable">$fieldName</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">,</span> <span class="token variable">$formData</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#000000&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;#111111&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;#222222&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">}</span>
</code></pre></div>`,16))])}const b=o(i,[["render",d]]);export{f as __pageData,b as default};
